// ============================================================
// WF2-3 · Code · "เลือก 3 ไฟล์ล่าสุด" (ไม่นับเดือนปัจจุบัน)
// วางต่อจาก node "List PLC" (Google Drive: search ไฟล์ในโฟลเดอร์ PLC)
// ชื่อไฟล์ "PLC | YYYYMM | ..." → เอา 3 เดือนล่าสุด "ที่จบแล้ว" (ข้ามเดือนปัจจุบัน+อนาคต)
//   เช่น ตอนนี้เดือน 7 (202607) → ใช้ 202606, 202605, 202604 (เดือน 6,5,4)
// ส่งต่อ 3 items (มี id) ให้ node "อ่าน PLC" อ่าน Sheet1 ทีละไฟล์
// ============================================================

const now = new Date();
const curYm = now.getFullYear() * 100 + (now.getMonth() + 1);   // เดือนปัจจุบัน YYYYMM

const files = $input.all().map(it => it.json);
const ym = files.map(f => {
  const name = f.name || f.title || f.originalFilename || '';
  const m = String(name).match(/(20\d{4})/);   // YYYYMM
  return { id: f.id, name, ym: m ? Number(m[1]) : 0 };
}).filter(x => x.id && x.ym > 0 && x.ym < curYm);   // < ปัจจุบัน = เดือนที่จบแล้วเท่านั้น

ym.sort((a, b) => b.ym - a.ym);   // ล่าสุดก่อน
return ym.slice(0, 3).map(x => ({ json: x }));

// ============================================================
// WF2-3 · Code · "เลือกไฟล์ Breakdown" (ทุกเดือนตั้งแต่ปี 2026 ที่จบแล้ว)
// วางต่อจาก node "List Breakdown" (Google Drive: search ไฟล์ในโฟลเดอร์รายงานการหยุดเครื่องจักร)
// ชื่อไฟล์: "รายงานการหยุดเครื่องจักร (Machine Breakdown) เดือน 06 | มิถุนายน 2026"
//   → เดือน = เลขหลัง "เดือน" | ปี = เลข 4 หลักตัวท้าย → ym = YYYYMM
// กรอง: ym ≥ 202601 (ตั้งแต่ปี 2026) และ ym < เดือนปัจจุบัน (เอาเฉพาะเดือนที่จบแล้ว)
// ส่งต่อทุกไฟล์ที่ผ่าน (สะสมทุกเดือน — ขึ้นเดือนใหม่จะได้เดือนก่อนเพิ่มเองอัตโนมัติ)
// ============================================================

const MIN_YM = 202601;                                            // ตั้งแต่ ม.ค. 2026
const now = new Date();
const curYm = now.getFullYear() * 100 + (now.getMonth() + 1);     // เดือนปัจจุบัน

const out = [];
for (const it of $input.all()) {
  const f = it.json;
  const name = String(f.name || f.title || f.originalFilename || '');
  const mm = name.match(/เดือน\s*(\d{1,2})/);
  const yy = name.match(/(20\d{2})(?!\d)/g);
  if (!mm || !yy) continue;
  const ym = Number(yy[yy.length - 1]) * 100 + Number(mm[1]);
  if (!f.id || ym < MIN_YM || ym >= curYm) continue;               // นอกช่วง / เดือนปัจจุบัน → ข้าม
  out.push({ json: { id: f.id, name, ym } });
}
out.sort((a, b) => a.json.ym - b.json.ym);   // เก่า → ใหม่
return out;

// ============================================================
// WF2-3 (COMBINED · สายรีเฟรช) · Code · "คำนวณ MachineStats"
// รวม 2 มิติที่ต้องอัปเดตเรื่อยๆ → เขียนทับชีต MachineStats
//
//  • ซ่อมเฉลี่ย (ชม./ครั้ง) ← "รายงานการหยุดเครื่องจักร" (ทุกเดือนตั้งแต่ปี 2026 ที่จบแล้ว)
//      ใช้เฉพาะ "แถวสรุป" = คอลัมน์ "วันที่" มีข้อความ "รวมเวลาที่หายไปทั้งสิ้น"
//      ชม. = คอลัมน์ "สูตร" (HH:MM:SS) · ครั้ง = คอลัมน์ "ลำดับครั้ง"
//      เฉลี่ย = Σชม. ÷ Σครั้ง   (หมายเหตุ: วันที่ "เครื่องไม่หยุด" นับเป็น 1 ครั้ง 0 ชม.)
//      node ที่ต้องมี: "หยุดเครื่อง PF8/3" "หยุดเครื่อง PF8/5" ... "หยุดเครื่อง ASB250/3"
//
//  • ไฟเฉลี่ยตอนผลิต (kW) ← PLC 3 เดือนล่าสุด (Demand > 5) · node "อ่าน PLC"
//
// ไม่มีข้อมูล → เว้นว่าง (combined ให้คะแนนกลาง 0.5)
// ============================================================

const RUN_THRESHOLD_KW = 5;
const MARK = 'รวมเวลาที่หายไปทั้งสิ้น';                     // ตัวชี้ว่าเป็นแถวสรุป
const MACHINES = ['PF8/3', 'PF8/5', 'PF8/6', 'PF8/7', 'PF8/8', 'TE', 'ASB250/3'];   // node = "หยุดเครื่อง "+m

function pick(row, prefix) { for (const k of Object.keys(row)) if (k.replace(/\s+/g, ' ').trim().startsWith(prefix)) return row[k]; return ''; }
const norm = m => (String(m || '').trim() === 'TE1' ? 'TE' : String(m || '').trim());
function hms(v) {                                            // "01:15:00" → 1.25 ชม.
  const s = String(v ?? '').trim();
  if (!s) return 0;
  const p = s.split(':');
  const h = parseInt(p[0]) || 0, mi = parseInt(p[1]) || 0, se = parseInt(p[2]) || 0;
  return h + mi / 60 + se / 3600;
}
const toInt = v => { const n = parseInt(String(v ?? '').replace(/[^\d-]/g, ''), 10); return isNaN(n) ? 0 : n; };

// ---- ซ่อมเฉลี่ยต่อเครื่อง (จากแถวสรุปของรายงานหยุดเครื่อง ทุกเดือนที่อ่านมา) ----
const rep = {};
for (const m of MACHINES) {
  let hrs = 0, cnt = 0;
  try {
    for (const it of $('หยุดเครื่อง ' + m).all()) {
      const row = it.json;
      const marker = String(pick(row, 'วันที่') ?? '');
      if (!marker.includes(MARK)) continue;                  // เอาเฉพาะแถวสรุป
      hrs += hms(pick(row, 'สูตร'));
      cnt += toInt(pick(row, 'ลำดับครั้ง'));
    }
  } catch (e) { /* ไม่มี node นี้ */ }
  if (cnt > 0) rep[m] = Math.round(hrs / cnt * 1000) / 1000;
}

// ---- ไฟเฉลี่ยตอนผลิตต่อเครื่อง (จาก PLC) ----
const dem = {};
try {
  for (const it of $('อ่าน PLC').all()) {
    const mac = norm(pick(it.json, 'Mac') || it.json['Mac']);
    const d = parseFloat(String(pick(it.json, 'Demand') ?? it.json['Demand'] ?? '').replace(/,/g, ''));
    if (mac && !isNaN(d) && d > RUN_THRESHOLD_KW) { dem[mac] = dem[mac] || { s: 0, n: 0 }; dem[mac].s += d; dem[mac].n++; }
  }
} catch (e) {}
const eng = {};
for (const m in dem) if (dem[m].n) eng[m] = Math.round(dem[m].s / dem[m].n * 100) / 100;

// ---- รวมเป็นแถว ----
const all = [...new Set([...MACHINES, ...Object.keys(rep), ...Object.keys(eng)])];
const ordered = [...MACHINES.filter(m => all.includes(m)), ...all.filter(m => !MACHINES.includes(m))];
return ordered.map(m => ({
  json: {
    'เครื่องจักร': m,
    'ซ่อมเฉลี่ย': (m in rep) ? rep[m] : '',
    'ไฟเฉลี่ย': (m in eng) ? eng[m] : '',
  }
}));

// ============================================================
// WF2-3 · Code · "กำหนดเครื่องจักร + คำนวณเวลาผลิต" (v2.0)
// Standalone — ความรู้ฝังในไฟล์ ไม่ต้องอ่าน spreadsheet DATA
// v2.0: สร้างตารางจากข้อมูลจริงครบทุกเครื่อง (PF8/3,5,7,8, TE,
