// ---- กฎพิเศษตามน้ำหนัก (ตรวจก่อนตารางเสมอ) — เครื่องเปลี่ยนตามน้ำหนัก ----
const SPECIAL_RULES = [
  { core: 'ขวด Vince 1000', spec: '37 ±1', machine: 'PF8/5', ct: 28.00, cap: 1028.57, good: 94.67  },
  { core: 'ขวด Vince 1000', spec: '34 ±1', machine: 'TE',    ct: 4.39,  cap: 820.05,  good: 100.00 },
  { core: 'ขวดนูบูน 1000',  spec: '42 ±1', machine: 'PF8/5', ct: 28.00, cap: 1028.57, good: 87.82  },
  { core: 'ขวดนูบูน 1000',  spec: '36 ±1', machine: 'TE',    ct: 4.42,  cap: 1628.96, good: 95.75  },
];

// ---- helpers ----
const norm = s => String(s ?? '').replace(/\s+/g, ' ').trim().toLowerCase();
const num = v => {
  if (v === null || v === undefined || v === '') return null;
  const n = parseFloat(String(v).replace(/[,\s]/g, ''));
  return isNaN(n) ? null : n;
};
const round2 = v => Math.round(v * Math.pow(10, CONFIG.ROUND_HOURS_DP)) / Math.pow(10, CONFIG.ROUND_HOURS_DP);

// ขนาด (ml) = ตัวเลขมากสุดใน core name; รองรับ "ลิตร" (เลข ≤10 → ×1000)
const volumeOf = coreName => {
  const s = String(coreName);
  const nums = (s.match(/\d+(?:\.\d+)?/g) || []).map(Number);
  if (!nums.length) return null;
  let v = Math.max(...nums);
  if (/ลิตร|liter|litre/i.test(s) && v <= 10) v *= 1000;
  return v;
};
// น้ำหนัก (g) = ตัวเลขแรกของ spec ส่วนที่ 3 เช่น "22.7 ±1" -> 22.7
const weightOf = spec => {
  const m = String(spec ?? '').match(/\d+(?:\.\d+)?/);
  return m ? parseFloat(m[0]) : null;
};

function findEntry(coreName, code) {
  const nCore = norm(coreName);
  const nCode = norm(code);
  if (nCode) {
    const byCode = KPI_TABLE.find(e => e.code && norm(e.code) === nCode);
    if (byCode) return { entry: byCode, exact: true };
  }
  let hit = KPI_TABLE.find(e => norm(e.name) === nCore);
  if (hit) return { entry: hit, exact: true };
  if (nCore) {
    hit = KPI_TABLE.find(e => nCore.includes(norm(e.name)) || norm(e.name).includes(nCore));
    if (hit) return { entry: hit, exact: false };
  }
  return null;
}

// สินค้าใหม่: หาสินค้าใกล้เคียงที่สุดด้วยน้ำหนัก + ขนาด (ต้องมีน้ำหนัก spec)
function estimateFromNearest(weight, volume) {
  if (weight === null) return null;
  let best = null;
  for (const e of KPI_TABLE) {
    let d = Math.abs(e.wt - weight) * CONFIG.WEIGHT_FACTOR;
    if (volume !== null && e.vol !== null) d += Math.abs(e.vol - volume) * CONFIG.VOLUME_FACTOR;
    const better =
      !best ||
      d < best.d ||
      (d === best.d && e.good !== null && best.entry.good === null); // เสมอ: เลือกตัวที่มี %ของดี
    if (better) best = { entry: e, d };
  }
  return best;
}

function planOne(r) {
  const fullName = String(r['ชื่อสินค้า'] ?? '').trim();
  const parts = fullName.split('|').map(p => p.trim());
  const coreName = parts[0] || '';
  const weightSpec = parts[2] || '';
  const code = r['รหัสสินค้า'] ?? null;
  const qty = num(r['จำนวนที่ต้องผลิตเพิ่ม (ใบ)']);

  let machine = null, ct = null, cap = null, good = null, entryCode = null;
  let source = 'ไม่พบข้อมูล';
  let note = '';

  const rule = SPECIAL_RULES.find(x => norm(coreName).includes(norm(x.core)) && weightSpec === x.spec);
  const found = rule ? null : findEntry(coreName, code);

  if (rule) {
    // 1) กฎพิเศษตามน้ำหนัก
    machine = rule.machine; ct = rule.ct; cap = rule.cap; good = rule.good;
    source = 'กฎพิเศษ'; entryCode = rule.code ?? null;
  } else if (found) {
    // 2) เจอในตารางอ้างอิง
    const e = found.entry;
    machine = e.machine; ct = e.ct; cap = e.cap; good = e.good; source = e.source; entryCode = e.code ?? null;
    if (!found.exact) note = `จับคู่จากชื่อใกล้เคียง: ${e.name}`;
  } else {
    // 3) สินค้าใหม่ -> ประมาณการจากสินค้าใกล้เคียง
    const est = estimateFromNearest(weightOf(weightSpec), volumeOf(coreName));
    if (est) {
      const e = est.entry;
      machine = e.machine; ct = e.ct; cap = e.cap;
      source = 'ประมาณการ';
      const lowConf = est.d > CONFIG.LOW_CONFIDENCE_DISTANCE ? ' ความเชื่อมั่นต่ำ —' : '';
      note = `สินค้าใหม่${lowConf} อ้างอิง ${e.name} (${e.wt} g / ${e.vol} ml, ระยะห่าง ${Math.round(est.d * 10) / 10}) ตรวจสอบก่อนใช้จริง`;
    } else {
      note = 'สินค้าใหม่ ไม่ระบุ spec น้ำหนัก (เช่น "19 ±1") จึงประมาณการไม่ได้ กรุณาระบุน้ำหนักหรือเพิ่มข้อมูลใน reference';
    }
  }

  // 4) เวลาผลิต = จำนวน ÷ กำลังผลิต
  let hours = null;
  if (qty === null || qty <= 0) {
    note = note || 'จำนวนที่ต้องผลิตไม่ถูกต้อง คำนวณเวลาไม่ได้';
  } else if (cap) {
    hours = round2(qty / cap);
  }

  return {
    ...r,
    'ชื่อสินค้า': fullName,
    'รหัสสินค้า': code || entryCode || null,
    'จำนวนที่ต้องผลิตเพิ่ม (ใบ)': qty,
    'เครื่องจักร': machine,
    'Cycle Time (s)': ct,
    'กำลังผลิตจริง (ใบ/ชม)': cap,
    'เวลาผลิต (ชม)': hours,
    '%ของดีอ้างอิง': good,
    'แหล่งข้อมูล': source,
    'หมายเหตุ': note,
  };
}

