// Product Data
const PD={};
try{ for(const it of $('อ่าน Product Data').all()){ const row=it.json; const code=String(pick(row,'Code')||'').trim(); if(!code)continue;
  const color=String(pick(row,'Product Color')||'').trim();
  (PD[code]=PD[code]||{})[color]={ resin:clean(pick(row,'Resin Type')), bag:clean(pick(row,'Bag size')), calW:fnum(pick(row,'Cal-Weight')), pack:fnum(pick(row,'Packing')), mbType:clean(pick(row,'Masterbatch Type')), mbRatio:fnum(pick(row,'Masterbatch Mixing Ratio')) };
} }catch(e){}
const matOf=(code,color)=>(PD[code]&&PD[code][color])||null;

const MACHINE_DEFECT={ 'PF8/8':1.435,'PF8/3':2.029,'TE':2.372,'PF8/7':3.904,'PF8/5':7.223,'ASB250/3':12.144 };
const REPAIR={},ENERGY={};
try{ for(const it of $('อ่าน MachineStats').all()){ const m=String(pick(it.json,'เครื่องจักร')||'').trim(); if(!m)continue; REPAIR[m]=fnum(pick(it.json,'ซ่อมเฉลี่ย')); ENERGY[m]=fnum(pick(it.json,'ไฟเฉลี่ย')); } }catch(e){}

// (2a) เวลาว่างล่าสุดของแต่ละเครื่อง จากตารางที่มีอยู่
const machineFreeAt={};
try{ for(const it of $('อ่านตารางผลิต').all()){ const row=it.json; const m=String(pick(row,'เครื่องจักร')||'').trim(); if(!m)continue;
  const fin=parseDT(pick(row,'วันที่สิ้นสุดผลิตสินค้า'),pick(row,'เวลาสิ้นสุดผลิตสินค้า'));
  if(fin&&(!machineFreeAt[m]||fin>machineFreeAt[m])) machineFreeAt[m]=fin;
} }catch(e){}

const now=new Date();
const ymd=`${pad(now.getFullYear()%100,2)}${pad(now.getMonth()+1,2)}${pad(now.getDate(),2)}`;
const today=fmtD(now);
const shiftStart=()=>{ const d=new Date(); d.setHours(START_HOUR,0,0,0); return d; };
const addHours=(b,h)=>new Date(b.getTime()+h*3600*1000);

// (1) รวมสินค้าซ้ำทั้ง input -> รวมจำนวน + ใช้เครื่องเดียว
const mergedAll={};
for(const it of $input.all()){
  const r=it.json;
  const machine=String(r['เครื่องจักร']??'').trim();
  const qty=num(r['จำนวนที่ต้องผลิตเพิ่ม (ใบ)']);
  if(!machine||qty<=0)continue;
  const name=r['ชื่อสินค้า']??''; const code=String(r['รหัสสินค้า']??'').trim(); const color=colorOf(name);
  const key=[name,code,color].join(' ¦ ');
  const cap=fnum(r['กำลังผลิตจริง (ใบ/ชม)']); const hrs=num(r['เวลาผลิต (ชม)']); const date=toYMD(r['วันที่ผลิต']);
  const mat=matOf(code,color)||{resin:null,bag:null,calW:null,pack:null,mbType:null,mbRatio:null};
  if(mergedAll[key]){ const e=mergedAll[key]; e.qty+=qty; e.hoursSum+=hrs; if(date&&(!e.date||date<e.date))e.date=date; e.dup++; }
  else mergedAll[key]={ machine,name,code,color,qty,hoursSum:hrs,cap,date,dup:1, resin:mat.resin,bag:mat.bag,calW:mat.calW,pack:mat.pack,mbType:mat.mbType,mbRatio:mat.mbRatio };
}
const byMachine={};
for(const e of Object.values(mergedAll)){
  e.hours=(e.cap&&e.cap>0)?Math.round(e.qty/e.cap*100)/100:e.hoursSum;   // เวลา = จำนวนรวม ÷ กำลังผลิต
  (byMachine[e.machine]=byMachine[e.machine]||[]).push(e);
}

// (2) จัดกลุ่มเป็นใบ (bins)
const warnings=[]; const bins=[];
for(const [machine,prods] of Object.entries(byMachine)){
  const cap=slotCap(machine); const groups={};
  for(const p of prods){
    if(!p.resin) bins.push({machine,cap,resin:'',date:p.date,items:[p]});
    else { const key=p.resin+' ¦ '+(p.mbType||'(ไม่มีสี)')+' ¦ '+(p.date||''); (groups[key]=groups[key]||[]).push(p); }
  }
  for(const list of Object.values(groups)){
    const resin=list[0].resin, gdate=list[0].date; list.sort((a,b)=>b.qty-a.qty);
    let bin=null;
    for(const p of list){
      if(bin){ const bags=new Set(bin.items.map(x=>x.bag)); if((bags.has(p.bag)||bags.size<2)&&bin.items.length<cap){ bin.items.push(p); continue; } }
      bin={machine,cap,resin,date:gdate,items:[p]}; bins.push(bin);
    }
  }
}

// (2b) เรียงใบตามเครื่อง + วันที่วางแผน แล้วไล่คิวไม่ให้เวลาชนกัน
bins.sort((a,b)=>{ if(a.machine!==b.machine)return a.machine<b.machine?-1:1;
  const da=(a.date?atHour(a.date):shiftStart()).getTime(); const db=(b.date?atHour(b.date):shiftStart()).getTime(); return da-db; });


// (2c) เตรียมข้อมูลจัดตารางต่อใบ: จำนวนคน (สินค้าเดียว=1, หลายสินค้า=2), เวลาผลิต, วันแผน
for(const bin of bins){
  bin.workers = new Set(bin.items.map(p=>p.name)).size<=1?1:2;
  bin.dur = bin.items.reduce((m,p)=>Math.max(m,p.hours),0);
  bin.planned = bin.date?atHour(bin.date):shiftStart();
}

// ---- ตัวจัดตารางแบบจำกัดคนงาน 4 คนต่อเนื่องตลอด 24 ชม. (ลำดับ=คิวเดิม + เติมคนว่าง: ข้ามไปหยิบใบถัดไปที่คนพอ+เครื่องว่างได้) ----
function scheduleBins(bins, machineFreeAt) {
  const MAX = 4;
  const ms = d => d.getTime();
  const addH = (base, h) => new Date(base.getTime() + h * 3600 * 1000);
  let free = MAX;
  const running = [];              // {end(ms), workers}
  const queue = bins.slice();      // priority order
  const mfree = {};                // machine -> free-at (ms)
  for (const k in machineFreeAt) if (machineFreeAt[k]) mfree[k] = ms(machineFreeAt[k]);
  const machFree = m => (mfree[m] != null ? mfree[m] : -Infinity);
  const elig = b => Math.max(ms(b.planned), machFree(b.machine));   // earliest time a bin could start

  let t = queue.length ? Math.min(...queue.map(b => ms(b.planned))) : 0;
  let guard = 0;
  while ((queue.length || running.length) && guard++ < 1000000) {
    // 1) ปล่อยงานที่เดินเสร็จ ณ เวลา t -> คืนคน
    for (let i = running.length - 1; i >= 0; i--) if (running[i].end <= t) { free += running[i].workers; running.splice(i, 1); }
    // 2) เริ่มใบตามคิว เท่าที่คนพอ (ใบไหนคนไม่พอ = ข้ามไปหยิบใบถัดไปที่คนพอ+เครื่องว่าง เพื่อเติมคนให้เต็ม ไม่ปล่อยว่าง)
    for (let i = 0; i < queue.length; i++) {
      const b = queue[i];
      if (ms(b.planned) > t) continue;      // ยังไม่ถึงวันแผน
      if (machFree(b.machine) > t) continue; // เครื่องยังไม่ว่าง
      if (free >= b.workers) {
        b.start = new Date(t); b.end = addH(b.start, b.dur);
        free -= b.workers; running.push({ end: ms(b.end), workers: b.workers });
        mfree[b.machine] = ms(b.end);         // เครื่องไม่ว่างจนจบใบนี้
        queue.splice(i, 1); i--;
      } else continue;                         // คนไม่พอใบนี้ -> ข้ามไปหยิบใบถัดไปที่คนพอ+เครื่องว่าง (เติมคนว่าง)
    }
    if (!queue.length && !running.length) break;
    // 3) เดินเวลาไปเหตุการณ์ถัดไป: งานเดินเสร็จ (คืนคน) หรือ ใบใหม่ถึงกำหนด/เครื่องว่าง
    const nextEnd = running.length ? Math.min(...running.map(r => r.end)) : Infinity;
    let nextElig = Infinity;
    for (const b of queue) { const e = elig(b); if (e > t && e < nextElig) nextElig = e; }
    let nt = Math.min(nextEnd, nextElig);
    if (!isFinite(nt) || nt <= t) nt = t + 3600 * 1000;   // safety กันค้าง
    t = nt;
  }
  for (const b of bins) if (!b.start) { b.start = new Date(b.planned.getTime()); b.end = addH(b.start, b.dur); }
  for (const k in mfree) machineFreeAt[k] = new Date(mfree[k]);
  return bins;
}

// (2d) จัดตาราง (คนว่างเมื่อเครื่องเดินเสร็จ -> ไปเริ่มใบถัดไปในคิว)
const machineFreeAt0 = { ...machineFreeAt };   // เก็บตารางเดิมไว้ก่อน (splitFill re-schedule จากฐานเดิม)
scheduleBins(bins, machineFreeAt);

// (2e) ซอยงานก้อนใหญ่ไปเครื่องว่างเพื่อเติมคนว่าง (สินค้า→เครื่องที่เคยผลิตได้+กำลังผลิต จากตารางคุณภาพ)
const MACHINE_OPTIONS = {"ขวดอนันดา 350":{"PF8/3":1566.1},"ขวดเซ็นทรัล 350":{"PF8/3":1566.1},"ขวด Vince 500":{"PF8/3":1565.2,"PF8/5":1066.7},"ขวดปาปาแพค 200 KR":{"PF8/3":1566.1,"TE":1623.4},"ขวดอนันดา 320":{"PF8/3":1566.1},"ขวดโฮมเฟรชมาร์ท 1500 (OX Series)":{"PF8/5":1000},"ขวดเบลมองด์ 500":{"PF8/5":993.1},"ขวด 1000 กรีนเมท":{"PF8/5":1066.7},"ขวดนูบูน 1000":{"PF8/5":1028.6,"TE":1629},"ขวด Vince 1000":{"PF8/5":1028.6,"TE":820},"ขวด 400 กรีนเมท":{"PF8/7":1714.3,"PF8/8":2087},"ขวด 400 BSC":{"PF8/7":1774.5,"PF8/8":2088.5},"ขวดนูบูน 500":{"PF8/7":1785.9},"ขวดไคโอ 350":{"PF8/7":1804.2,"PF8/8":2057.6},"ขวดไอดีล 500":{"PF8/7":1809.6},"ขวดเคลลี่ 450":{"PF8/7":1794.2,"PF8/8":2063.2},"ขวดปาปาแพค 220 KR":{"PF8/8":2066},"ขวดออนเดอะเทเบิ้ล 330 (OB Series) V1":{"PF8/8":2054.2},"ขวด CPC 1 ลิตร":{"ASB250/3":621.5},"ขวดมะพร้าว 1000":{"ASB250/3":643.9},"ขวดเหล่าธงสิงห์ 1000":{"ASB250/3":1041.6},"ขวดฉั่วฮะเส็ง 380":{"TE":1841.4},"ขวดซากุระ 700":{"TE":1472.4},"ขวดปาปาแพค 150 KR":{"TE":1618},"ขวดทานตะวัน 730":{"TE":1629},"ขวดกรุงสยาม 450 V2":{"TE":1690.1},"ขวดอินโนเฟรช 465":{"TE":1375.6}};
function splitFillPass(bins){
  const MAX=4, MIN_H=SPLIT_MIN_H, MIN_QTY=SPLIT_MIN_QTY, MAXIT=12, MAX_PP=SPLIT_MAX_PER_PRODUCT, MAX_TOT=SPLIT_MAX_TOTAL;
  const NOSPLIT=new Set(SPLIT_NOSPLIT); const cN=s=>String(s||'').split('|')[0].trim();
  const idleWin=()=>{ const ev=[...new Set(bins.flatMap(b=>[b.start.getTime(),b.end.getTime()]))].sort((a,b)=>a-b); const w=[];
    for(let i=0;i<ev.length-1;i++){ const t=ev[i],t2=ev[i+1]; const run=bins.filter(b=>b.start.getTime()<=t&&b.end.getTime()>t); const u=run.reduce((s,b)=>s+b.workers,0); if(u<MAX&&run.length)w.push({a:t,b:t2,idle:MAX-u,running:run}); } return w; };
  const dom=bin=>bin.items.reduce((bst,it)=>(!bst||it.hours>bst.hours)?it:bst,null);
  const sndH=(bin,ex)=>bin.items.reduce((m,it)=>(it!==ex&&it.hours>m)?it.hours:m,0);
  const busy=(M,a,b)=>bins.some(bin=>bin.machine===M&&bin.start.getTime()<b&&bin.end.getTime()>a);
  const nextStart=(M,a)=>{ let n=Infinity; for(const bin of bins)if(bin.machine===M){const s=bin.start.getTime(); if(s>=a&&s<n)n=s;} return n; };
  const qtyAll=()=>bins.reduce((s,b)=>s+b.items.reduce((x,i)=>x+(+i.qty||0),0),0);
  const total0=qtyAll(); const splitCount={}; let did=0;
  const resched=()=>{ for(const b of bins){delete b.start;delete b.end;} scheduleBins(bins,{...machineFreeAt0}); };
  for(let iter=0;iter<MAXIT&&did<MAX_TOT;iter++){
    const wins=idleWin().filter(w=>(w.b-w.a)>=MIN_H*3600e3).sort((x,y)=>(y.idle*(y.b-y.a))-(x.idle*(x.b-x.a)));
    let best=null;
    for(const w of wins){
      for(const B of w.running){
        if(!B.items||!B.items.length)continue;
        const it=dom(B), pc=cN(it.name), opt=MACHINE_OPTIONS[pc];
        if(!opt||NOSPLIT.has(pc)||(splitCount[pc]||0)>=MAX_PP)continue;
        const rateSrc=opt[B.machine]||(it.hours?it.qty/it.hours:0); if(!rateSrc||it.hours<MIN_H)continue;
        const floorH=sndH(B,it);
        for(const M of Object.keys(opt)){
          if(M===B.machine||busy(M,w.a,w.b))continue;
          const rateDst=opt[M]; if(!rateDst)continue;
          const winH=(Math.min(w.b,nextStart(M,w.a))-w.a)/3600e3; if(winH<MIN_H)continue;
          const tDst=Math.min(it.qty/(rateSrc+rateDst),winH); let qtyDst=Math.floor(rateDst*tDst);
          if(qtyDst>=it.qty)qtyDst=it.qty-MIN_QTY; if(qtyDst<MIN_QTY)continue;
          const gain=it.hours-Math.max((it.qty-qtyDst)/rateSrc,floorH); if(gain<MIN_H)continue;
          if(!best||gain>best.gain)best={B,it,pc,M,rateSrc,rateDst,qtyDst,gain};
        }
      }
      if(best)break;
    }
    if(!best)break;
    const {B,it,pc,M,rateSrc,rateDst,qtyDst}=best;
    it.qty-=qtyDst; it.hours=it.qty/rateSrc; B.dur=B.items.reduce((m,x)=>Math.max(m,x.hours),0);
    const ni={...it,qty:qtyDst,cap:rateDst,hours:qtyDst/rateDst,machine:M};
    bins.push({machine:M,cap:slotCap(M),resin:it.resin,date:B.date,planned:B.planned,items:[ni],workers:1,dur:qtyDst/rateDst,split:true,splitFrom:B.machine});
    warnings.push(`ซอย ${cN(it.name)} ${qtyDst.toLocaleString()} ใบ → ${M} (เติมคนว่าง)`);
    splitCount[pc]=(splitCount[pc]||0)+1; did++; resched();
  }
  if(Math.abs(qtyAll()-total0)>1) throw new Error('จำนวนรวมเพี้ยน');
  return did;
}
if(SPLIT_FILL){ try{ splitFillPass(bins); }catch(e){ warnings.push('splitFill ข้าม: '+e.message); scheduleBins(bins,{...machineFreeAt0}); } }

// 3) สร้างแถวใบสั่งผลิต (เวลาเริ่ม/จบจากตัวจัดตาราง) — ไม่มี "รอบ" แล้ว
const rows=[];
for(const bin of bins){
  const cap=bin.cap; const items=bin.items.slice().sort((a,b)=>b.qty-a.qty); const N=items.length;
  if(N>cap) warnings.push(`เครื่อง ${bin.machine}: กลุ่ม resin เดียวกันมี ${N} ตัว > ${cap} ช่อง`);
  const slotsPer=items.map(()=>1); slotsPer[0]+=Math.max(0,cap-N);
  const slotName=[],slotQty=[];
  items.forEach((p,i)=>{ const cnt=slotsPer[i],base=Math.floor(p.qty/cnt),rem=p.qty-base*cnt; for(let s=0;s<cnt;s++){ slotName.push(p.name); slotQty.push(base+(s===cnt-1?rem:0)); } });
  while(slotName.length<4){ slotName.push(''); slotQty.push(''); }

  const start=bin.start, end=bin.end;
  const workers=bin.workers;
  const prim=items[0];
  const resinType=prim.resin;
  const resinKg=Math.round(items.reduce((s,p)=>s+p.qty*(p.calW||0),0)/1000*10)/10||null;
  const mbType=prim.mbType;
  const mbKg=(resinKg!=null&&prim.mbRatio)?Math.round(resinKg*prim.mbRatio*100)/100:null;
  const bagList=[...new Set(items.map(p=>p.bag).filter(Boolean))];
  const bag1=prim.bag||bagList[0]||null;
  const bag2=bagList.find(b=>b!==bag1)||null;
  const bagsFor=bt=>{ let s=0,any=false; for(const p of items) if(p.bag===bt){ any=true; if(p.pack>0)s+=Math.ceil(p.qty/p.pack); } return any?s:null; };
  const dupNote=items.filter(p=>p.dup>1).map(p=>`รวมซ้ำ "${p.name}" ${p.dup} รายการ`).join(' | ');
  const warnNote=warnings.filter(w=>w.includes(bin.machine)).join(' | ');

  rows.push({ machine:bin.machine, start, workers, json:{
    'รอบ':null,'วันที่ออกเอกสาร':today,'เครื่องจักร':bin.machine,
    'วันที่เริ่มผลิตสินค้า':fmtD(start),'เวลาเริ่มผลิตสินค้า':fmtT(start),
    'ชื่อสินค้า แม่พิมพ์ตัวที่ 1':slotName[0],'ชื่อสินค้า แม่พิมพ์ตัวที่ 2':slotName[1],'ชื่อสินค้า แม่พิมพ์ตัวที่ 3':slotName[2],'ชื่อสินค้า แม่พิมพ์ตัวที่ 4':slotName[3],
    'เลขที่ใบสั่งผลิต':null,'ประเภทการผลิต':'ขวดเปล่า','จำนวนคนงาน':workers,
    'วันที่สิ้นสุดผลิตสินค้า':fmtD(end),'เวลาสิ้นสุดผลิตสินค้า':fmtT(end),
    'จำนวนสั่งผลิต1':slotQty[0],'จำนวนสั่งผลิต2':slotQty[1],'จำนวนสั่งผลิต3':slotQty[2],'จำนวนสั่งผลิต4':slotQty[3],
    'ประเภทเม็ดวัตถุดิบ':resinType,'ประเภทเม็ดสี':mbType,
    'ขนาดถุงมาตรฐาน ชนิดที่ 1':bag1,'ขนาดถุงมาตรฐาน ชนิดที่ 2':bag2,
    'น้ำหนักเม็ดวัตถุดิบ':resinKg,'น้ำหนักเม็ดสี':mbKg,
    'จำนวนถุงที่ใช้ทั้งหมด ชนิดที่ 1':bag1?bagsFor(bag1):null,'จำนวนถุงที่ใช้ทั้งหมด ชนิดที่ 2':bag2?bagsFor(bag2):null,
    '_หมายเหตุ':[dupNote,warnNote].filter(Boolean).join(' | '),
  }});
}

// 4) ไม่มีรอบ — เรียงตามเวลาเริ่ม (แล้วเครื่อง) ใส่เลขที่ใบสั่งผลิต ('รอบ' ปล่อยว่าง)
rows.sort((a,b)=> (a.start.getTime()-b.start.getTime()) || (a.machine<b.machine?-1:a.machine>b.machine?1:0));
return rows.map((r,i)=>{ r.json['เลขที่ใบสั่งผลิต']=`DBM-${ymd}-${mCode(r.machine)}-${pad(i+1,3)}`; return {json:r.json}; });
})();

// ============================================================
// WF2-3 · Code · "สรุปออเดอร์เมื่อวาน (FM-DSM-001)"  (v2 robust)
// FM-DSM-001 เป็นชีตแบบฟอร์ม (แถว 1 ว่าง, หัวจริงอยู่แถว 2) ทำให้ n8n
// เดา header ผิดได้ → โหนดนี้ "ประกอบตารางเอง" แล้วหาแถวหัวจริงจากเนื้อหา
// (แถวที่มีคำว่า Product Name + Backlog Quantity) จับคอลัมน์ตามตำแหน่ง
// จึงทำงานได้ไม่ว่า n8n จะ set header row เป็นแถวไหน
//
//  1) กรองเฉพาะแถว "PO. Receiving Date" = เมื่อวาน (เวลาไทย +7)
//  2) ตัดขยะ/ยกเลิก: ไม่มี PO No / Backlog ไม่ใช่ตัวเลข / PO.Status = CANCEL* / แถวสรุป
//  3) จำนวนที่ต้องผลิต = Backlog Quantity − Production Status (ว่าง=0) ; ข้ามถ้า ≤ 0
//  4) ส่งออกฟิลด์ตรงกับ flow เดิม (ชื่อสินค้า/รหัสสินค้า/จำนวนที่ต้องผลิตเพิ่ม (ใบ)/วัน Delivery)
// ============================================================

const items = $input.all();
if (!items.length) return [];

// ---- helpers ----
const pad = (n) => String(n).padStart(2, '0');
const norm = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();
const num = (v) => {
  if (v === null || v === undefined) return null;
  const s = String(v).replace(/[,\s]/g, '');
  if (s === '' || s === '-' || s.toLowerCase() === 'none') return null;
  const n = parseFloat(s);
  return isNaN(n) ? null : n;
};
function toYMD(v) {
  if (v === null || v === undefined || v === '') return null;
  if (v instanceof Date && !isNaN(v)) return `${v.getUTCFullYear()}-${pad(v.getUTCMonth() + 1)}-${pad(v.getUTCDate())}`;
  const s = String(v).trim();
  if (!s) return null;
  if (/^\d+(\.\d+)?$/.test(s)) {                     // serial ของ Google Sheets
    const n = parseFloat(s);
    if (n > 20000 && n < 80000) {
      const dt = new Date(Date.UTC(1899, 11, 30) + Math.round(n) * 86400000);
      return `${dt.getUTCFullYear()}-${pad(dt.getUTCMonth() + 1)}-${pad(dt.getUTCDate())}`;
    }
  }
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);    // ISO / Y-m-d
  if (m) { let Y = +m[1]; if (Y > 2400) Y -= 543; return `${Y}-${pad(+m[2])}-${pad(+m[3])}`; }
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})/);     // d/m/Y
  if (m) { let Y = +m[3]; if (Y > 2400) Y -= 543; if (Y < 100) Y += 2000; return `${Y}-${pad(+m[2])}-${pad(+m[1])}`; }
  const d = new Date(s);
  return isNaN(d) ? null : `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
}

// ---- เมื่อวาน ตามเวลาไทย ----
const BKK = 7 * 3600 * 1000;
const nowBkk = new Date(Date.now() + BKK);
const yest = new Date(Date.UTC(nowBkk.getUTCFullYear(), nowBkk.getUTCMonth(), nowBkk.getUTCDate()) - 24 * 3600 * 1000);
const targetYMD = `${yest.getUTCFullYear()}-${pad(yest.getUTCMonth() + 1)}-${pad(yest.getUTCDate())}`;
const todayDMY = `${pad(nowBkk.getUTCDate())}/${pad(nowBkk.getUTCMonth() + 1)}/${nowBkk.getUTCFullYear()}`;  // วันตั้งแผน = จุดเริ่มนับ 'ผลิตแล้ว' ของ flow re-plan

// ---- (A) ประกอบตารางเองจากผลลัพธ์ n8n ----
// key ที่ n8n ตั้ง = ค่าจริงของแถวที่มันเอาไปเป็น header (คือ 1 แถวของชีต)
// ตัด row_number (ฟิลด์ที่ n8n เติมเอง) ออกก่อน
const rawKeys = Object.keys(items[0].json).filter((k) => k !== 'row_number');
const asRow = (obj) => rawKeys.map((k) => obj[k]);
const allRows = [rawKeys.slice(), ...items.map((it) => asRow(it.json))];

// ---- (B) หาแถวหัวจริง จากเนื้อหา ----
const isHeader = (row) =>
  row.some((c) => norm(c).includes('Product Name')) && row.some((c) => norm(c).includes('Backlog Quantity'));
const hIdx = allRows.findIndex(isHeader);
if (hIdx === -1) {
  throw new Error(
    'หาแถวหัวคอลัมน์ FM-DSM-001 ไม่เจอ (ต้องมี "Product Name" + "Backlog Quantity") — ' +
    'ตรวจว่า node "อ่าน FM-DSM-001" อ่านชีตถูกแท็บ · ตัวอย่างคีย์: ' + rawKeys.slice(0, 8).join(' | ')
  );
}
const hdr = allRows[hIdx].map(norm);
const ci = (subs) => { for (const s of [].concat(subs)) { const i = hdr.findIndex((h) => h.includes(s)); if (i >= 0) return i; } return -1; };
const cName = ci('Product Name'), cCode = ci('Product Code'),
      cRecv = ci(['PO. Receiving Date', 'Receiving Date']),
      cShip = ci(['Schedule Shipping Date', 'Shipping Date']),
      cPOst = ci(['PO. Status', 'PO Status']),
      cProd = ci('Production Status'), cBack = ci('Backlog Quantity'), cPONo = ci(['PO No']);
if ([cName, cCode, cRecv, cBack].some((i) => i < 0)) {
  throw new Error('หัวคอลัมน์ FM-DSM-001 ไม่ครบ — เจอหัว: ' + hdr.filter(Boolean).join(' | '));
}

// ---- (C) ประมวลผลแถวข้อมูล (หลังแถวหัว) ----
const body = allRows.slice(hIdx + 1);
const out = [];
let kept = 0, skDate = 0, skJunk = 0, skCancel = 0, skQty = 0;
for (const row of body) {
  if (toYMD(row[cRecv]) !== targetYMD) { skDate++; continue; }

  const poNo = String(row[cPONo] ?? '').trim();
  if (!poNo || poNo === '-') { skJunk++; continue; }
  if (num(row[cBack]) === null) { skJunk++; continue; }
  if (String(row[cPOst] ?? '').toUpperCase().includes('CANCEL')) { skCancel++; continue; }
  if (/สรุป|ð/.test(row.map((c) => String(c ?? '')).join(' '))) { skJunk++; continue; }

  const qty = Math.round((num(row[cBack]) || 0) - (num(row[cProd]) || 0));
  if (qty <= 0) { skQty++; continue; }

  const name = String(row[cName] ?? '').trim();   // ชื่อเต็มมี | คั่น (core|ชนิด|น้ำหนัก|สี)
  const code = String(row[cCode] ?? '').trim();
  if (!name || !code) { skJunk++; continue; }
  const ship = String(row[cShip] ?? '').trim();   // คงรูปแบบวันเดิม (d/m/Y) ให้ตรงชีต

  out.push({ json: {
    'ชื่อสินค้า': name,
    'รหัสสินค้า': code,
    'จำนวนที่ต้องผลิตเพิ่ม (ใบ)': qty,
    'วัน Delivery': ship,
    'วันที่ผลิต': todayDMY,
    'เครื่องจักร': '',
    '_PO No.': poNo,
    '_วันรับออเดอร์': targetYMD,
  } });
  kept++;
}

console.log(`[FM-DSM] เมื่อวาน=${targetYMD} | headerRowIdx=${hIdx} | เข้าเงื่อนไข ${kept} | ข้าม: วันไม่ตรง ${skDate}, ยกเลิก ${skCancel}, ขยะ ${skJunk}, ≤0 ${skQty}`);
return out;

// ============================================================
// "ปรับชื่อสินค้า (ส่วน 2 = ขวดเปล่า)" — flow หลัก
// ชื่อสินค้าแบ่ง 4 ส่วนด้วย "|" : [1]=ชื่อ/รุ่น(core) · [2]=รายละเอียด · [3]=น้ำหนัก · [4]=สี
// เปลี่ยน "ส่วนที่ 2" ของทุกสินค้าให้เป็น "ขวดเปล่า" ก่อนเขียนลง Planning + รายการ T1
// วางคั่น: "เลือกเครื่อง (รวม 3 มิติ)" -> โหนดนี้ -> (เขียน Planning T1 + สร้างใบสั่งผลิต)
// ปลอดภัย: core=ส่วน1 / สี=ส่วน4 ไม่ถูกแตะ → การเลือกเครื่อง/วัตถุดิบ/จับคู่ ไม่เปลี่ยน
// ============================================================
function fixPart2(name) {
  const p = String(name == null ? '' : name).split('|');
  if (p.length >= 2) {                              // มีส่วนที่ 2 ให้แก้
    const lead = (p[1].match(/^\s*/) || [''])[0];   // คงช่องว่างหน้า-หลังเดิมไว้ (รูปแบบ " | " เหมือนเดิม)
    const trail = (p[1].match(/\s*$/) || [''])[0];
    p[1] = lead + 'ขวดเปล่า' + trail;
  }
  return p.join('|');
}

return $input.all().map(it => {
  const j = { ...it.json };
  if (j['ชื่อสินค้า'] != null && j['ชื่อสินค้า'] !== '') j['ชื่อสินค้า'] = fixPart2(j['ชื่อสินค้า']);
  return { json: j };
});
